<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from "vue";
import AppIcon from "../components/AppIcon.vue";
import { api, post } from "../lib/api";

const datasets = ref([]), dataset = ref("vatsalabench"), runs = ref([]), jobs = ref([]);
const selectedId = ref(""), detail = ref(null), sample = ref(null), sampleId = ref(""), predictions = ref([]);
const pane = ref("history"), section = ref("metrics"), error = ref(""), loading = ref(true), detailLoading = ref(false);
const modal = ref(false), starting = ref(false), configured = ref(false), search = ref(""), answerFilter = ref("all");
const taskDetail = ref(null), activeTaskId = ref(""), showKey = ref(false);
const form = reactive({ mode: "check", count: 1, model: "deepseek-v4-flash", base_url: "https://api.deepseek.com", provider: "openai", api_key: "", auto_score: true });
const info = computed(() => datasets.value.find(d => d.id === dataset.value));
const filtered = computed(() => runs.value.filter(r => r.dataset === dataset.value && `${r.name} ${r.model}`.toLowerCase().includes(search.value.toLowerCase())));
const visibleJobs = computed(() => jobs.value.filter(j => j.dataset === dataset.value));
const busy = computed(() => jobs.value.some(j => ["running", "queued", "cancelling"].includes(j.status)));
const samples = computed(() => detail.value?.samples || []);
const answers = computed(() => (sample.value?.answers || []).filter(a => answerFilter.value === "all" || (answerFilter.value === "wrong" ? a.verdict?.correct === 0 : a.verdict?.correct === 1)));
const states = { completed: "已完成", partial: "部分完成", failed: "未完成", running: "运行中", queued: "等待中", cancelling: "取消中", cancelled: "已取消", interrupted: "已中断" };
const kinds = { batch: "六维评测", quality: "历史回放", check: "数据检查", comparison: "方法对照" };
let timer, selectionVersion = 0, sampleVersion = 0, disposed = false, polling = false;

function value(metric) {
  if (metric?.value == null) return "NA";
  return metric.unit === "percent" ? `${(metric.value * 100).toFixed(metric.value * 100 % 1 ? 2 : 0)}%` : Number(metric.value).toFixed(2);
}
function date(value) { return new Date(value).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hour12: false }); }
function title(run) { return run.kind === "batch" ? `六维评测 · ${run.planned} 条样本` : kinds[run.kind] || "概念分类评测"; }
function expected(gold) { const item = gold?.expected; return Array.isArray(item) ? item.join("；") : item ?? "未提供"; }
function predicted(row) { const item = row.actual ?? row.predicted ?? row.prediction ?? row.label; return typeof item === "object" ? JSON.stringify(item) : item ?? "—"; }
async function refreshRuns() {
  runs.value = (await api("/api/evaluations/runs")).items;
  const choices = runs.value.filter(r => r.dataset === dataset.value);
  if (!choices.some(r => r.id === selectedId.value)) await selectRun(choices.find(r => r.kind === "batch") || choices[0]);
}
async function chooseDataset(id) {
  if (dataset.value === id) return;
  dataset.value = id; sample.value = null; predictions.value = []; search.value = "";
  const choices = runs.value.filter(r => r.dataset === id);
  await selectRun(choices.find(r => r.kind === "batch") || choices[0]);
}
async function selectRun(run) {
  const version = ++selectionVersion; ++sampleVersion;
  selectedId.value = run?.id || ""; detail.value = null; sample.value = null; predictions.value = []; error.value = "";
  if (!run) return;
  detailLoading.value = true;
  try {
    const data = await api(`/api/evaluations/runs/${run.id}`);
    if (version !== selectionVersion || disposed) return;
    detail.value = data; section.value = "metrics";
    if (data.samples?.length) await selectSample(data.samples[0].id);
    else if (data.dataset !== "vatsalabench" && data.kind !== "check") { const rows = (await api(`/api/evaluations/runs/${run.id}/predictions`)).items; if (version === selectionVersion && !disposed) predictions.value = rows; }
  } catch (e) { if (version === selectionVersion) error.value = e.message; }
  finally { if (version === selectionVersion) detailLoading.value = false; }
}
async function selectSample(id) {
  const version = ++sampleVersion, run = selectedId.value;
  sampleId.value = id; sample.value = null; answerFilter.value = "all";
  try {
    const data = await api(`/api/evaluations/runs/${run}/samples/${encodeURIComponent(id)}`);
    if (version === sampleVersion && selectedId.value === run && !disposed) sample.value = data;
  } catch (e) { if (version === sampleVersion) error.value = e.message; }
}
async function refresh() {
  error.value = "";
  try { await refreshRuns(); jobs.value = (await api("/api/evaluations/tasks")).items; }
  catch (e) { error.value = e.message; }
}
async function poll() {
  if (polling || disposed) return;
  polling = true;
  try {
    const wasBusy = busy.value;
    jobs.value = (await api("/api/evaluations/tasks")).items;
    if (activeTaskId.value) taskDetail.value = await api(`/api/evaluations/tasks/${activeTaskId.value}`);
    if (wasBusy && !busy.value) await refreshRuns();
  } catch (e) { if (!disposed) error.value = e.message; }
  finally { polling = false; }
}
async function openTask(id) { activeTaskId.value = id; pane.value = "tasks"; await poll(); }
async function cancel(id) { try { await post(`/api/evaluations/tasks/${id}/cancel`, {}); await poll(); } catch (e) { error.value = e.message; } }
function closeModal() { modal.value = false; form.api_key = ""; showKey.value = false; }
async function start() {
  starting.value = true; error.value = "";
  try {
    const task = await post("/api/evaluations/tasks", { ...form, dataset: dataset.value });
    closeModal(); await openTask(task.id);
  } catch (e) { error.value = e.message; }
  finally { starting.value = false; }
}
function taskResult(job) { return runs.value.find(r => r.path.startsWith(job.path)); }
async function viewResult(job) { const run = taskResult(job); if (run) { pane.value = "history"; await selectRun(run); } }
onMounted(async () => {
  try { const data = await api("/api/evaluations/datasets"); datasets.value = data.items; configured.value = data.model_configured; if (configured.value) { form.model = data.configured_model; form.provider = data.configured_provider; form.base_url = data.configured_base_url; } await refresh(); }
  catch (e) { error.value = e.message; }
  finally { loading.value = false; }
  timer = setInterval(poll, 3000);
});
onUnmounted(() => { disposed = true; clearInterval(timer); ++selectionVersion; ++sampleVersion; });
</script>

<template>
  <div class="page eval-page">
    <header class="eval-heading">
      <div><div class="eval-eyebrow"><span/> EVALUATION LAB</div><h1>评测中心</h1><p>选择数据集，运行评测，追踪每一次方法改动。</p></div>
      <div class="eval-actions"><button class="eval-icon" aria-label="刷新评测记录" @click="refresh"><AppIcon name="refresh"/></button><button class="eval-primary" :disabled="loading || busy" @click="modal = true"><AppIcon name="plus"/>新建评测</button></div>
    </header>
    <div v-if="error" class="eval-error" role="alert">{{ error }}<button aria-label="关闭提示" @click="error=''">×</button></div>
    <div class="eval-datasets" aria-label="选择评测数据集">
      <button v-for="d in datasets" :key="d.id" class="eval-dataset" :class="[d.color, { selected: dataset === d.id }]" :aria-pressed="dataset === d.id" @click="chooseDataset(d.id)">
        <div class="eval-dataset-top"><span class="eval-dataset-icon"><AppIcon :name="d.id==='vatsalabench'?'constellation':d.id==='memory-150'?'layers':'book'"/></span><span class="eval-count">{{ d.count }} <small>条样本</small></span><AppIcon v-if="dataset===d.id" name="check" class="eval-selected"/></div>
        <h3>{{ d.name }}</h3><span class="eval-dataset-label">{{ d.label }}</span><p>{{ d.description }}</p><div class="eval-dataset-bottom"><span>{{ d.version }}</span><span>{{ dataset===d.id?'当前数据集':'选择数据集' }} <span>↗</span></span></div>
      </button>
      <div v-if="loading" class="eval-loading">正在读取本地数据集…</div>
    </div>
    <nav class="eval-nav" aria-label="评测视图"><button :class="{active:pane==='history'}" @click="pane='history'">评测记录 <span>{{ filtered.length }}</span></button><button :class="{active:pane==='tasks'}" @click="pane='tasks'">运行任务 <span :class="{pulsing:busy}">{{ visibleJobs.length }}</span></button><div class="eval-nav-note"><AppIcon name="database"/>{{ info?.name }}<span>·</span>{{ info?.metrics.length }} 项指标</div></nav>

    <div v-if="pane==='history'" class="eval-workbench">
      <aside class="eval-runs"><div class="eval-runs-heading"><h3>历史批次</h3><span>{{ filtered.length }} RUNS</span></div><label class="eval-search"><AppIcon name="search"/><input v-model="search" placeholder="搜索批次或模型" aria-label="搜索评测记录"/></label><div class="eval-runlist">
        <button v-for="r in filtered" :key="r.id" class="eval-run" :class="{selected:r.id===selectedId}" @click="selectRun(r)"><div><span class="eval-status" :class="r.status"><span/>{{ states[r.status] }}</span><time>{{ date(r.created_at) }}</time></div><strong>{{ title(r) }}</strong><small>{{ r.model || (r.kind==='check'?'文件完整性与结构':r.kind==='comparison'?'新旧方法逐项对照':'原始运行记录') }}</small><footer><span>{{ r.completed }}/{{ r.planned }} {{ r.kind==='check'?'条已检查':'已完成' }}</span><AppIcon name="chevron"/></footer></button>
        <div v-if="!filtered.length && !loading" class="eval-empty"><AppIcon name="flask"/><p>还没有评测记录</p><button @click="modal=true">创建第一次评测 ↗</button></div>
      </div></aside>
      <section class="eval-detail">
        <div v-if="detailLoading" class="eval-empty large">正在读取评测记录…</div>
        <template v-else-if="detail">
          <header class="eval-detail-heading"><div><span class="eval-kicker">{{ info?.name }} / {{ kinds[detail.kind] || '概念分类' }}</span><h2>{{ title(detail) }}</h2><p><AppIcon name="clock"/>{{ date(detail.created_at) }}<span>·</span>{{ detail.model || '本地检查' }}</p></div><span class="eval-status" :class="detail.status"><span/>{{ states[detail.status] }}</span></header>
          <div class="eval-detail-tabs"><button v-for="[key,label] in [['metrics','指标概览'],['answers','逐题结果'],['report','报告与配置']]" :key="key" :class="{active:section===key}" @click="section=key">{{ label }}</button><span>{{ detail.review==='reviewed'?'人工复核完成':detail.review==='model'?'模型初评 · 待复核':'原始运行记录' }}</span></div>
          <template v-if="section==='metrics'">
            <div class="eval-coverage"><div><span class="eval-small-dot"/>{{ detail.kind==='check'?'数据检查完成':'质量完成' }} <b>{{ detail.completed }} / {{ detail.planned }}</b></div><span v-if="detail.efficiency">效率完成 <b>{{ detail.efficiency.samples }} / {{ detail.efficiency.planned_samples }}</b></span><small v-if="detail.kind==='batch'">按各指标有效样本计分</small></div>
            <div v-if="detail.metrics.length" class="eval-metric-grid"><article v-for="m in detail.metrics" :key="m.key" class="eval-metric"><div><span>{{ m.dimension }}</span><b>{{ m.key }}</b></div><strong :class="{low:m.value!=null && m.value<.5, na:m.value==null}">{{ value(m) }}</strong><h4>{{ m.name }}</h4><footer><span>有效 {{ m.valid_n ?? '—' }}{{ m.planned_n ? ` / ${m.planned_n}` : '' }}</span><span v-if="m.key==='CR-AUC'">初始答对事实</span></footer><div class="eval-bar"><span :style="{width:`${Math.min(1,Math.max(0,m.value||0))*100}%`}"/></div></article></div>
            <div v-else-if="detail.check" class="eval-check"><span class="eval-check-icon"><AppIcon name="check"/></span><h3>{{ detail.check.samples_with_errors ? '发现数据异常' : '数据检查通过' }}</h3><p>{{ detail.check.checked_samples }} 条样本 · {{ detail.check.samples_with_errors }} 条异常</p><div v-if="detail.check.totals"><span v-for="[key,label] in [['sessions','历史会话'],['messages','原始消息'],['probes','测试问题']]" :key="key"><b>{{ detail.check.totals[key]?.toLocaleString() }}</b>{{ label }}</span></div></div>
            <div v-else class="eval-empty"><AppIcon name="activity"/><p>此轮保存了原始输出，尚未汇总指标。</p><button @click="section=detail.kind==='comparison'?'report':'answers'">查看{{ detail.kind==='comparison'?'对照报告':'逐题结果' }} ↗</button></div>
            <div v-if="detail.efficiency" class="eval-efficiency"><div class="eval-section-title"><h3>效率观测</h3><span v-if="detail.efficiency.conditional">仅 {{ detail.efficiency.samples }} 个完成实例 · 整批效率为 NA</span><span v-else>独立效率实例</span></div><div class="eval-efficiency-grid"><article><span>查询延迟 P95</span><strong>{{ detail.efficiency.L95 == null ? 'NA' : detail.efficiency.L95.toFixed(2) }}<small>秒</small></strong></article><article><span>摊销 Token 消耗</span><strong>{{ detail.efficiency.ATC == null ? 'NA' : Math.round(detail.efficiency.ATC).toLocaleString() }}<small>/ 查询</small></strong></article><article><span>存储放大系数</span><strong>{{ detail.efficiency.SAF == null ? 'NA' : detail.efficiency.SAF.toFixed(2) }}<small>倍</small></strong></article></div></div>
          </template>
          <template v-if="section==='answers'">
            <div v-if="samples.length" class="eval-answer-area"><div class="eval-sample-list" aria-label="选择测试样本"><button v-for="(s,i) in samples" :key="s.id" :class="{active:sampleId===s.id}" @click="selectSample(s.id)"><span>{{ String(i+1).padStart(2,'0') }}</span><b>{{ s.id }}</b><small :class="s.status">{{ s.completed }}/{{ s.planned }}</small></button></div>
              <div v-if="sample?.error" class="eval-failure"><b>本次运行未完成</b><p>{{ sample.error.message }}</p><span>已保存 {{ sample.ingestion_count }} 个导入片段</span></div>
              <div v-if="sample?.answers.length" class="eval-answer-filter"><span>{{ sample.answers.length }} 个检查点 <small v-if="sample.failed_operations">· {{ sample.failed_operations }} 次写入操作失败</small></span><select v-model="answerFilter" aria-label="筛选判分"><option value="all">全部结果</option><option value="wrong">未通过</option><option value="correct">通过</option></select></div>
              <details v-for="a in answers" :key="a.id" class="eval-answer"><summary><code>{{ a.id }}</code><span>{{ a.question }}</span><b :class="a.verdict?.correct===0?'wrong':a.verdict?.correct===1?'correct':''">{{ a.verdict ? a.verdict.correct ? '通过' : '未通过' : '待评分' }}</b><AppIcon name="chevron"/></summary><div class="eval-answer-body"><label>系统回答</label><p>{{ a.answer }}</p><div class="eval-gold"><label>评分参考</label><p>{{ expected(a.gold) }}</p><small>{{ a.gold?.rule }}</small></div><div v-if="a.verdict" class="eval-verdict"><label>判分依据</label><p>{{ a.verdict.reason }}</p></div><details class="eval-evidence"><summary>检索证据 <b>{{ a.references.length }}</b><span>{{ a.seconds?.toFixed(2) }}s</span></summary><article v-for="r in a.references" :key="r.id"><code>{{ r.module }}</code><p>{{ r.content }}</p><pre v-if="r.evidence_context">{{ r.evidence_context }}</pre></article><p v-if="!a.references.length">本次未召回证据</p></details></div></details>
              <div v-if="!sample" class="eval-empty">读取样本结果…</div><div v-else-if="!sample.answers.length && !sample.error" class="eval-empty">此样本尚未产生回答</div><div v-else-if="sample.answers.length && !answers.length" class="eval-empty">没有符合筛选条件的回答</div>
            </div>
            <div v-else-if="predictions.length" class="eval-predictions"><table><thead><tr><th>编号</th><th>测试输入</th><th>参考</th><th>预测</th><th>结果</th></tr></thead><tbody><tr v-for="r in predictions" :key="r.id"><td><code>{{ r.id }}</code></td><td>{{ r.example || r.input || r.text }}</td><td>{{ r.expected }}</td><td>{{ predicted(r) }}</td><td><span class="eval-status" :class="r.correct?'completed':'failed'">{{ r.correct?'通过':'未通过' }}</span></td></tr></tbody></table></div>
            <div v-else class="eval-empty">此轮没有逐题回答记录</div>
          </template>
          <div v-if="section==='report'" class="eval-report"><div class="eval-section-title"><h3>归档位置</h3></div><code class="eval-path">{{ detail.path }}</code><details open><summary>评测报告</summary><pre>{{ detail.report || '此轮尚未生成文字报告。' }}</pre></details><details><summary>运行配置</summary><pre>{{ JSON.stringify(detail.config,null,2) }}</pre></details></div>
        </template>
        <div v-else-if="!detailLoading" class="eval-empty large"><AppIcon name="flask"/><h3>每一次改动，都可以验证</h3><p>选择左侧记录，查看指标与逐题证据。</p></div>
      </section>
    </div>

    <section v-else class="eval-task-page"><header class="eval-section-title"><h3>运行任务</h3><span>同时运行 1 个评测任务</span></header><div v-if="!visibleJobs.length" class="eval-empty large"><AppIcon name="play"/><h3>准备开始一次评测</h3><p>选择数据集和测试模式，进度会显示在这里。</p><button class="eval-primary" @click="modal=true">新建评测</button></div><div v-else class="eval-task-layout"><aside><button v-for="j in visibleJobs" :key="j.id" class="eval-task" :class="{active:activeTaskId===j.id}" @click="openTask(j.id)"><span class="eval-status" :class="j.status"><span/>{{ states[j.status] }}</span><strong>{{ j.mode==='check'?'数据检查':`完整评测 · ${j.count} 条` }}</strong><small>{{ date(j.created_at) }}</small></button></aside><div v-if="taskDetail" class="eval-task-console"><header><div><h3>{{ taskDetail.mode==='check'?'数据检查':'评测执行' }}</h3><code>{{ taskDetail.id }}</code></div><button v-if="['queued','running'].includes(taskDetail.status)" class="eval-secondary" @click="cancel(taskDetail.id)">取消任务</button><button v-else-if="taskResult(taskDetail)" class="eval-primary" @click="viewResult(taskDetail)">查看结果 <AppIcon name="chevron"/></button></header><div class="eval-live-status"><span class="eval-status" :class="taskDetail.status"><span/>{{ states[taskDetail.status] }}</span><p>{{ taskDetail.message }}</p></div><div class="eval-progress" v-for="p in taskDetail.progress" :key="p.sample_id"><b>{{ p.sample_id }}</b><span>已导入 {{ p.ingested }} 个片段</span><span>回答 {{ p.answered }}/12</span></div><label>执行日志</label><pre>{{ taskDetail.log || '等待进程输出…' }}</pre><code class="eval-path">{{ taskDetail.path }}</code></div><div v-else class="eval-empty">选择任务查看进度</div></div></section>

    <div v-if="modal" class="eval-modal-backdrop" @click.self="closeModal" @keydown.esc="closeModal"><section role="dialog" aria-modal="true" aria-labelledby="eval-dialog-title" class="eval-modal"><header><div class="eval-modal-symbol"><AppIcon name="flask"/></div><button class="eval-icon" aria-label="关闭新建评测" @click="closeModal">×</button></header><h2 id="eval-dialog-title">新建评测</h2><p>{{ info?.name }} · {{ info?.count }} 条样本</p><form @submit.prevent="start"><fieldset><legend>评测模式</legend><div class="eval-mode-options"><label :class="{active:form.mode==='check'}"><input type="radio" v-model="form.mode" value="check"/><b>数据检查</b><small>检查文件、样本结构与校验值</small></label><label :class="{active:form.mode==='full'}"><input type="radio" v-model="form.mode" value="full"/><b>{{ dataset==='vatsalabench'?'完整六维评测':'完整评测' }}</b><small>运行模型并记录逐项结果</small></label></div></fieldset><label v-if="dataset==='vatsalabench' && form.mode==='full'" class="eval-form-field">新增样本数<select v-model.number="form.count"><option v-for="n in 5" :key="n" :value="n">{{ n }} 条样本</option></select><small>固定种子选择样本，方便对照复测。每条含 12 个质量检查点、3 次独立效率查询。</small></label><template v-if="form.mode==='full'"><div class="eval-form-row"><label class="eval-form-field">模型名称<input v-model="form.model" required maxlength="120"/></label><label class="eval-form-field">接口协议<select v-model="form.provider"><option value="openai">OpenAI 兼容</option><option value="anthropic">Anthropic</option></select></label></div><label class="eval-form-field">服务地址<input v-model="form.base_url" type="url" required/></label><label class="eval-form-field">API Key<span class="eval-key"><input v-model="form.api_key" :type="showKey?'text':'password'" autocomplete="off" :placeholder="configured?'留空使用服务端配置':'输入模型 API Key'" :required="!configured"/><button type="button" @click="showKey=!showKey">{{ showKey?'隐藏':'显示' }}</button></span></label><label v-if="dataset==='vatsalabench'" class="eval-checkbox"><input type="checkbox" v-model="form.auto_score"/>完成后进行模型初评<span>支持后续人工复核</span></label><p v-if="dataset!=='vatsalabench'" class="eval-form-note">此数据集将运行全部 {{ info?.count }} 条样本。</p></template><div v-if="error" class="eval-error">{{ error }}</div><footer><button type="button" class="eval-secondary" @click="closeModal">取消</button><button class="eval-primary" type="submit" :disabled="starting || busy"><AppIcon name="play"/>{{ starting?'正在创建…':form.mode==='check'?'开始数据检查':'开始评测' }}</button></footer></form></section></div>
  </div>
